  boosted.phase=12;step(win,boosted,"year-rest");check(win.view(boosted).cards().stream().anyMatch(c->c.id().equals("phenom")),"Boost legendary choice");
  var elite=fresh();elite.age=18;elite.attributes.replaceAll((k,v)->70);elite.reputation=80;elite.contract=new GameState.Contract("furia","FURIA",3,5000,2028,"Titular",12);elite.phase=3;map(win,elite);check(elite.qualifiedMasters1&&elite.phase==4&&Calendar.match(elite),"Kickoff qualifies Masters");check(elite.series.size()==3&&elite.maps.size()==6&&elite.outcome==null,"Three MD3s, six maps and one qualification");var stat=elite.maps.get(0);check(stat.rounds()==stat.score()+stat.opponentScore()&&stat.deaths()<=stat.rounds(),"Plausible map rounds and deaths");check(stat.acs()==Math.round((double)stat.combatScore()/stat.rounds()*10)/10.0,"ACS from combat score and rounds");check(win.view(elite).statistics().kills()==elite.maps.stream().mapToInt(GameState.MapStats::kills).sum(),"Lifetime aggregation");map(win,elite);elite.phase=5;map(win,elite);check(elite.qualifiedMasters2,"Stage1 qualifies second Masters");elite.phase=8;map(win,elite);check(elite.qualifiedPlayoffs,"Stage2 qualifies playoffs");elite.phase=9;map(win,elite);check(elite.qualifiedChampions,"Playoffs qualify Champions");elite.phase=10;map(win,elite);check(elite.trophies.stream().anyMatch(t->t.name().contains("Champions")),"Champions trophy");
  int allCombat=elite.maps.stream().mapToInt(GameState.MapStats::combatScore).sum(),allRounds=elite.maps.stream().mapToInt(GameState.MapStats::rounds).sum();check(win.view(elite).statistics().acs()==Math.round((double)allCombat/allRounds*10)/10.0,"Weighted ACS");
  elite.phase=11;step(win,elite,"awards-team");check(elite.awards.stream().anyMatch(a->a.title().contains("Revelação")),"Annual awards derived from stats");
