  var loss=fresh();loss.phase=3;var prior=new LinkedHashMap<>(loss.attributes);map(lose,loss);check(loss.losses==16&&prior.entrySet().stream().allMatch(x->loss.attributes.get(x.getKey())>=x.getValue()),"Losing maps still supports permanent practice without skill loss");
  for(var engine:List.of(win,lose)){var career=fresh();int decisions=0;while(!career.ended){var old=new LinkedHashMap<>(career.attributes);var choices=engine.view(career).scene().choices();String id=career.pendingCards?choices.get(0).id():career.phase==2?(career.contract==null?"offer-0":"honor"):career.phase==12?"year-develop":quick(engine,career);step(engine,career,id);for(var entry:old.entrySet())check(career.attributes.get(entry.getKey())>=entry.getValue(),"Skills never fall across full career");check(career.money>=0&&career.energy>=0&&career.energy<=100&&career.stress>=0&&career.stress<=100,"Resource bounds");check(++decisions<1500,"Career terminates");}check(career.age==35&&career.seasons.size()==21&&career.cards.size()==21,"21 years 21 rewards");check(career.earnings==career.seasons.stream().mapToInt(GameState.Season::earnings).sum(),"Income reconciliation");rejects(()->choose(engine,career,"prep-aim"),"Ended career gated");}
  var retire=fresh();retire.age=23;retire.phase=12;step(win,retire,"retire");step(win,retire,win.view(retire).scene().choices().get(0).id());check(retire.ended&&retire.age==23,"Retirement after final card");
  var release=fresh();release.phase=2;release.contract=new GameState.Contract("furia","FURIA",3,500,2028,"Titular",12);release.money=999;rejects(()->choose(win,release,"release"),"Cannot afford release");release.money=1000;step(win,release,"release");check(release.contract==null&&release.phase==2&&release.money==0,"Release exact cost");
  var personal=fresh();var options=win.view(personal).activities();check(options.size()==4&&options.equals(win.view(personal).activities()),"Stable activities without rerolls");var activity=options.get(0);var attrs=new LinkedHashMap<>(personal.attributes);int originalPhase=personal.phase;win.act(personal,new GameEngine.Action("activity",activity.item().id(),personal.revision));check(personal.phase==originalPhase&&personal.activitySlots.size()==1&&personal.outcome!=null,"Activity does not advance and has immediate outcome");for(var entry:activity.gains().entrySet())check(personal.attributes.get(entry.getKey())==attrs.get(entry.getKey())+entry.getValue(),"Activity gain preview exact");ack(win,personal);rejects(()->win.act(personal,new GameEngine.Action("activity",activity.item().id(),personal.revision)),"Cannot repeat period activity");step(win,personal,"prep-team");check(win.view(personal).activities().stream().allMatch(GameEngine.ActivityView::available),"Next period unlocks activity");
  personal.phase=3;choose(win,personal,"series-play");ack(win,personal);rejects(()->win.act(personal,new GameEngine.Action("activity",win.view(personal).activities().get(0).item().id(),personal.revision)),"No activity between key rounds");
  for(var g:PersonalLife.GOALS){var goal=fresh();win.act(goal,new GameEngine.Action("goal",g.id(),goal.revision));ack(win,goal);rejects(()->win.act(goal,new GameEngine.Action("goal","contract",goal.revision)),"Goal cannot be replaced");switch(g.id()){case "contract"->goal.contract=new GameState.Contract("furia","FURIA",3,500,2026,"Titular",12);case "wins"->goal.seasonWins=3;case "voice"->goal.attributes.merge("communication",8,Integer::sum);case "community"->goal.followers+=1500;default->{for(int i=0;i<3;i++)goal.maps.add(new GameState.MapStats(2026,3,"VCB","Haven","MIBR","FURIA",true,13,8,20,10,5,5500,21,261.9,"2.00",true));}}goal.phase=12;int income=goal.earnings;step(win,goal,"year-rest");check(goal.goalSettled&&goal.goals.size()==1&&goal.goals.get(0).completed(),"Goal automatically assessed once");check(goal.earnings-income==g.cash()+(goal.contract==null?0:goal.contract.salary()),"Goal reward plus December salary exactly once");check(goal.earnings==goal.seasons.get(0).earnings(),"Goal included in season earnings");int earned=goal.earnings;step(win,goal,win.view(goal).scene().choices().get(0).id());check(goal.seasonGoal==null&&!goal.goalSettled&&goal.earnings==earned,"New year resets goal without second payment");}
  var failedGoal=fresh();win.act(failedGoal,new GameEngine.Action("goal","wins",0));ack(win,failedGoal);failedGoal.phase=12;var initial=new LinkedHashMap<>(failedGoal.attributes);step(win,failedGoal,"year-rest");check(!failedGoal.goals.get(0).completed()&&failedGoal.goals.get(0).cash()==0,"Unmet goal no reward");for(var entry:initial.entrySet())check(failedGoal.attributes.get(entry.getKey())>=entry.getValue(),"Unmet goal no skill loss");
  var tooLate=fresh();tooLate.phase=3;rejects(()->win.act(tooLate,new GameEngine.Action("goal","wins",0)),"Cannot select goal after seeing maps");check(Events.LIFE.size()==15,"Fifteen unexpected event templates");
  var interactive=fresh();interactive.phase=3;var stable=win.view(interactive).agenda();check(stable.equals(win.view(interactive).agenda())&&interactive.campaigns.isEmpty()&&interactive.series.isEmpty(),"Reading agenda never mutates or rolls fixtures");step(win,interactive,"series-play");check(interactive.match!=null&&interactive.maps.size()==1&&interactive.currentSeries.wins==1,"Opening map simulates before intervention");for(int i=0;i<3;i++)step(win,interactive,quick(win,interactive));check(interactive.series.size()==1&&interactive.maps.size()==2&&interactive.series.get(0).mode().equals("moment"),"Moment completes MD3 with all maps");check(interactive.series.get(0).maps().stream().map(GameState.MapStats::map).distinct().count()==2,"No repeated map in series");
  var run=fresh();run.pace="run";step(win,run,"run-prepare");check(run.phase==2&&run.reputation==4,"Run skips preparation but stops for contract");step(win,run,"offer-0");choose(win,run,"series-run");check(run.series.size()==4&&run.tourEvent&&run.phase==3,"Run batches four series and stops at dilemma");check(run.outcome.seriesResults().size()==4&&run.outcome.seriesResults().stream().allMatch(r->r.maps().size()==2),"Batch contains every series and map");int revision=run.revision;rejects(()->win.act(run,new GameEngine.Action("choice","series-run",revision-1)),"Stale batch cannot be repeated");ack(win,run);var event=Events.life(run);step(win,run,quick(win,run));check(!run.tourEvent&&run.phase==3&&run.seenLifeEvents.contains(Events.LIFE.indexOf(event)),"Dilemma resumes same competition without repeating its template");map(win,run);run.phase=5;map(win,run);run.phase=8;map(win,run);check(run.series.size()==26&&run.seriesWins==26&&run.wins==52,"Base calendar has 26 series and 52 winning maps");
  var stop=fresh();stop.phase=3;step(win,stop,"series-next");check(stop.series.isEmpty()&&stop.phase==3,"Fast advance stops before debut");step(win,stop,"series-sim");choose(win,stop,"series-next");check(stop.series.size()==4&&stop.tourEvent,"Fast advance cannot skip career event");ack(win,stop);
  var finalSeries=fresh();finalSeries.phase=10;finalSeries.age=18;finalSeries.qualifiedChampions=true;finalSeries.contract=new GameState.Contract("furia","FURIA",3,5000,2028,"Titular",12);map(win,finalSeries);check(finalSeries.series.size()==6&&finalSeries.series.get(0).bestOf()==5&&finalSeries.series.get(0).maps().size()==3,"Champions groups and playoffs culminate in an MD5");check(finalSeries.seriesWins==6&&finalSeries.titles==1,"Only one trophy for full tournament, not one per map");
  for(var engine:List.of(win,lose)){var vct=fresh();vct.age=18;vct.phase=3;vct.contract=new GameState.Contract("furia","FURIA",3,5000,2026,"Titular",12);int guard=0;while(vct.phase<11){step(engine,vct,quick(engine,vct));check(++guard<100,"Elite yearly route terminates");}int expected=engine==win?33:13;check(vct.series.size()==expected,"Elite annual volume follows qualifications: "+vct.series.size());check(vct.series.size()==vct.seriesWins+vct.seriesLosses,"Series reconciled");check(vct.maps.size()==vct.wins+vct.losses,"Maps reconciled");}
  var alternating=new GameEngine(new Random(1){int maps;@Override public int nextInt(int bound){return bound==100?(++maps%2==1?0:99):0;}});var md5=fresh();md5.phase=10;md5.age=18;md5.qualifiedChampions=true;md5.contract=new GameState.Contract("furia","FURIA",3,5000,2028,"Titular",12);var bracket=new GameState.Campaign();bracket.part="bracket";bracket.upperWins=3;md5.campaigns.put(10,bracket);step(alternating,md5,"series-sim");var five=md5.series.get(0);check(five.bestOf()==5&&five.wins()==3&&five.losses()==2&&five.maps().size()==5,"Full five-map final resolves exactly three map wins");check(five.maps().stream().map(GameState.MapStats::map).distinct().count()==5,"Five-map final has five different maps");
  for(int seed=1;seed<=4;seed++){for(int bits=0;bits<256;bits++){var route=fresh();route.phase=9;route.age=18;route.contract=new GameState.Contract("furia","FURIA",3,5000,2028,"Titular",12);var path=new GameState.Campaign();path.part="bracket";path.seed=seed;Tour.seedBracket(path);route.campaigns.put(9,path);int played=0;while(!path.done&&played<8){boolean won=(bits&(1<<played))!=0;var fixture=Tour.fixture(route);check(fixture.bestOf==3||fixture.bestOf==5,"Valid series format on every bracket path");Tour.result(route,won);played++;}check(path.done&&played<=7,"Every double-elimination path ends within bounded series");check(!path.champion||path.qualified,"Champion always qualified");}}
  int growing=0,eliteOffers=0,winning=0,total=0;Set<Integer> records=new HashSet<>();for(int seed=0;seed<16;seed++){var rngEngine=new GameEngine(new Random(seed));var career=rngEngine.create("Run"+seed,"BR","duelist","ranked","Jett",null);career.pace="run";int start=Catalog.overall(career),guard=0;while(career.age<21){var choices=rngEngine.view(career).scene().choices();String id=career.pendingCards?choices.get(0).id():career.phase==2?(career.contract==null?"offer-0":"honor"):career.phase==12?"year-develop":quick(rngEngine,career);step(rngEngine,career,id);check(++guard<400,"Run simulation progresses");}if(Catalog.overall(career)>start+20)growing++;if(career.series.stream().anyMatch(r->r.competition().startsWith("VCT")))eliteOffers++;winning+=career.seriesWins;total+=career.seriesWins+career.seriesLosses;records.add(career.seriesWins);}check(growing==16,"Every sampled standard career develops without requiring good RNG");check(eliteOffers>=12,"Most sampled careers can reach elite by 21");check(records.size()>8&&winning>total*.3&&winning<total*.85,"Balance sample has diverse competitive results, not forced losses or guaranteed titles");System.out.println("Balance sample: "+winning+"/"+total+" series wins; "+eliteOffers+"/16 elite paths; "+growing+"/16 growing careers.");
